import * as React from 'react'

import './success-check.css'

export type SuccessCheckProps = {
    /** Announced to screen readers, e.g. "Payment complete". */
    label: string
    /** Diameter in px. */
    size?: number
    color?: string
    className?: string
}

// A ring draws itself, then the tick, then a soft pop. Render it when the
// success happens: it carries role="status" so the label is announced.
const SuccessCheck = ({ label, size = 88, color = '#4ade80', className }: SuccessCheckProps) => (
    <span role="status" aria-label={label} className={['rad-fx-success', className].filter(Boolean).join(' ')} style={{ width: size, height: size, '--rad-fx-success-color': color } as React.CSSProperties}>
        <svg viewBox="0 0 52 52" aria-hidden="true" focusable="false">
            <circle className="rad-fx-success-ring" cx="26" cy="26" r="23" pathLength={1} />
            <path className="rad-fx-success-tick" d="M15 27 L23 34 L37 19" pathLength={1} />
        </svg>
    </span>
)

export default SuccessCheck

.rad-fx-success {
    display: inline-flex;
    animation: rad-fx-success-pop 400ms cubic-bezier(0.3, 1.6, 0.5, 1) 900ms both;
}

.rad-fx-success svg {
    width: 100%;
    height: 100%;
    fill: none;
    stroke: var(--rad-fx-success-color, #4ade80);
    stroke-width: 3;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.rad-fx-success-ring {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transform: rotate(-90deg);
    transform-origin: 50% 50%;
    animation: rad-fx-success-draw 600ms cubic-bezier(0.6, 0.1, 0.3, 1) forwards;
}

.rad-fx-success-tick {
    stroke-width: 3.5;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation: rad-fx-success-draw 350ms cubic-bezier(0.6, 0.1, 0.3, 1) 550ms forwards;
}

@keyframes rad-fx-success-draw { to { stroke-dashoffset: 0; } }

@keyframes rad-fx-success-pop {
    0% { transform: scale(1); }
    50% { transform: scale(1.08); }
    100% { transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-success, .rad-fx-success-ring, .rad-fx-success-tick { animation: none; stroke-dashoffset: 0; }
}

[data-rad-fx-motion='reduce'] .rad-fx-success,
[data-rad-fx-motion='reduce'] .rad-fx-success-ring,
[data-rad-fx-motion='reduce'] .rad-fx-success-tick { animation: none; stroke-dashoffset: 0; }
